import '../public-path';
import '../vendor';
import '../polyfills';
import '../utils/focus-ring';
import quicklink from 'quicklink';
import { load } from '@shopify/theme-sections';
import '../sections/header';
import '../../styles/theme.pcss';
import { Application } from '../modules/module/application';
import { MediaBreakpoints } from '../modules/static/media-breakpoints';
import { RichText } from '../modules/static/rich-text';
/* import { getElement } from '../utils/functional' */

import { externalLinks, internalLinks } from '../utils';
import { Animations } from '../utils/animations';
import { AnimatedHeader } from '../utils/animated-header'; // This can clear the cart on the cart page because of the remove links, don't use this on that

if (window.location.pathname !== '/cart' && !window.theme.isDevTheme) {
  window.addEventListener('load', () => {
    quicklink({
      // Can error on mailto links when on https
      ignores: [uri => uri.includes('mailto:'), uri => uri.includes('/account'), uri => uri.includes('/cart')]
    });
  });
}

window.BAO.application = Application.start();
window.BAO.mediaBreakpoints = new MediaBreakpoints();
window.BAO.animations = new Animations();
window.BAO.animatedHeader = new AnimatedHeader();
document.addEventListener('DOMContentLoaded', () => {
  load(['header']);
  externalLinks();
  internalLinks({
    elementsToOffset: [],
    hashesToIgnore: ['#recover']
  }); // eslint-disable-next-line no-new

  new RichText(); // If the device is iOS add a class to the body so we can do specific CSS for it

  if (!!navigator.platform && /iPad|iPhone|iPod/.test(navigator.platform)) {
    document.body.classList.add('is-iOS');
  }

  if (/^((?!chrome|android).)*safari/i.test(navigator.userAgent)) {
    document.body.classList.add('is-Safari');
  }
});