import Cookies from 'js-cookie';
export class AnimatedHeader {
  constructor() {
    this.element = null;
    this.element = document.querySelector('.hd-AnimatedHeader');
    this.onScroll = this.onScroll.bind(this);

    if (Cookies.get(this.cookieName) === 'true') {
      this.element.classList.add('hd-AnimatedHeader-hide');
    } else {
      Cookies.set(this.cookieName, 'true', {
        expires: 3650
      });
      this.element.classList.add('hd-AnimatedHeader-animate');
      document.querySelector('.hd-Header').classList.add('hd-Header-animate'); // window.addEventListener('scroll', this.onScroll)
    }
  }

  onScroll(event) {
    if (window.pageYOffset > 0) {
      window.removeEventListener('scroll', this.onScroll);
      this.element.classList.add('hd-AnimatedHeader-animate');
    }
  }

  get cookieName() {
    return 'BAO-animated-header';
  }

}