import { getElements } from '../../utils/functional';
const defaultSchema = {
  moduleAttribute: 'data-module',
  elAttribute: 'data-el'
};
export class Application {
  static start(element, schema) {
    const application = new Application(element, schema);
    application.start();
    return application;
  }

  constructor(element = document.documentElement, schema = defaultSchema) {
    this.modules = [];
    this.element = element;
    this.schema = schema;
  }

  async start() {
    await domReady();
    getElements("[".concat(this.schema.moduleAttribute, "]")).forEach(el => {
      const isLazy = el.hasAttribute('data-module-lazy');
      if (isLazy) return;
      return this.startModule(el, el.getAttribute(this.schema.moduleAttribute));
    });
  }

  startModule(el, name) {
    return import(
    /* webpackChunkName: "[request]" */
    "../".concat(name)).then(({
      default: Module
    }) => {
      this.modules.push(Module.build(el, this));
    });
  }

  registerModule(el) {
    return this.startModule(el, el.getAttribute(this.schema.moduleAttribute));
  }

  reinitialiseModules(el) {
    getElements("[data-module]", {
      context: el
    }).forEach(el => this.registerModule(el));
  }

}

function domReady() {
  return new Promise(resolve => {
    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', resolve);
    } else {
      resolve();
    }
  });
}